import base64
import re

def base64_to_image(b64_str, output_path):
    # 如果有 data URI 前缀，去掉它
    if "," in b64_str and b64_str.strip().startswith("data:"):
        b64_str = b64_str.split(",", 1)[1]
    # 去掉可能存在的换行和空白
    b64_str = re.sub(r"\s+", "", b64_str)
    # 补全 padding（长度不是 4 的倍数时）
    b64_str += "=" * (-len(b64_str) % 4)

    img_bytes = base64.b64decode(b64_str)
    with open(output_path, "wb") as f:
        f.write(img_bytes)



def main():
    b64_str = ""

    out_path = r"D:\project\python_code\LLM_work\LLM_prompt_test\hello_agents.png"

    base64_to_image(b64_str,out_path)




if __name__ == "__main__":
    main()